-- cell_components.sql  --  one clicked cell, its component scores and its cell facts
--
-- R twin: msens::scores_for_cells(con, tibble(cell_id, pct_covered = 100)) (msens/R/calc.R:286-334)
--   degenerates to exactly this for a single cell -- with one cell at pct 100 the blend is
--   sum(v * 100) / 100 = v -- plus the `cell` row itself (app_bundle.R:866-880's wide tile).
--   .component_of() is calc.R:224-228.
-- Pinned by: tests/fixtures/parity/{v7,v9}/cell_components_*.json, which is generated by that
--   single-cell scores_for_cells() call, so the degeneration is asserted, not assumed.
--
-- WHY A SEPARATE FILE rather than running sql/scores_for_cells.sql with a one-row place. Because
-- the click popup asks a different question: it wants the cell's OWN values (`area_km2`, `in_usa`,
-- `in_pra`) beside the components, it must answer for a cell OUTSIDE the study area too (the popup
-- says "outside US waters", it does not go blank), and it must never depend on a `place_cell` table
-- that a click has no reason to build. `in_usa` is returned RAW here -- NULL on v1-v7, which have no
-- such column (sql/cells_in_study_area.sql's header) -- so the caller can say "not recorded" rather
-- than inventing a FALSE.
--
-- Numbers never come from the tile server (master-plan D4): a clicked cell's score is read from the
-- wide Parquet tile, never by sampling a rendered COG pixel.
--
-- v10 P6: the suffix strip also takes the national scope's `_v10_global` / `_v10` (`extrisk_bird_v10_global`
-- and `primprod_v10` read "bird" and "primprod", like their ecoregion twins); `.component_of()`'s R twin
-- is unchanged for every v1-v9 key (the suffix is only ever at the end).
--
-- v10 P6: UNPIVOT INCLUDE NULLS (the standard form; the short `UNPIVOT tbl ON` form has no such
-- option) keeps a component the cell has no value for as a row with a NULL `v`; `include_null_rows`
-- (FALSE for every v1-v9 call) filters those rows back out, so only the national scope sees them (a
-- hollow slot, like a zone's absent component).
--
-- `cols` is the ident()-validated component column list (sql.ts's RAW_ALLOWLIST); a cell_id that is
-- not in any loaded tile returns zero rows, which is a real answer (off-grid or unscored), not an
-- error.
WITH c AS (
  SELECT cell_id, area_km2, in_usa, in_pra, {{cols}}
    FROM cell
   WHERE cell_id = {{cell_id}}
),
long AS (
  SELECT * FROM c
  UNPIVOT INCLUDE NULLS (v FOR metric_key IN ({{cols}}))
)
SELECT long.metric_key,
       long.v                                 AS val,
       regexp_replace(
         regexp_replace(
           regexp_replace(long.metric_key, 'extrisk_', ''),
           '(_ecoregion_rescaled|_v10_global|_v10)$', ''),
         '_', ' ')                            AS component,
       c.area_km2,
       c.in_usa,
       c.in_pra
  FROM long
 CROSS JOIN c
 WHERE regexp_matches(long.metric_key, {{metric_pattern}})
   AND ({{include_null_rows}} OR long.v IS NOT NULL)
   AND regexp_replace(
         regexp_replace(
           regexp_replace(long.metric_key, 'extrisk_', ''),
           '(_ecoregion_rescaled|_v10_global|_v10)$', ''),
         '_', ' ') <> 'all'
 ORDER BY long.metric_key
